using UnityEngine;
namespace Blocklands {
 public partial class CastleSystem {
  float nextSun,sunEnd;Transform sunScene;public bool SunbreakActive=>sunScene!=null;
  public bool StartSunbreakNow(){if(Game.RoyalIdentity)return false;nextSun=Time.time;return SunbreakUpdate();}
  bool SunbreakUpdate(){if(Game.RoyalIdentity){if(sunScene!=null){Destroy(sunScene.gameObject);sunScene=null;}return false;}if(sunScene!=null){if(Time.time<sunEnd)return true;Destroy(sunScene.gameObject);sunScene=null;if(palacePrincess!=null)palacePrincess.gameObject.SetActive(true);nextSun=Time.time+90;return false;}if(Time.time<nextSun||ProcessionActive)return false;
   sunScene=new GameObject("公主屋顶阳光休息区").transform;sunScene.SetParent(transform);sunScene.position=new Vector3(31,76,24);var a=sunScene.gameObject.AddComponent<RoyalArt>();Color pink=new Color(.91f,.52f,.71f),white=new Color(.95f,.92f,.83f);a.Piece("躺椅",new Vector3(0,.32f,0),new Vector3(1.3f,.25f,2),pink);a.Piece("椅背",new Vector3(0,.85f,.75f),new Vector3(1.3f,1.2f,.16f),white);a.Piece("遮阳伞杆",new Vector3(-1.4f,1.5f,0),new Vector3(.07f,3,.07f),white);a.Taper("遮阳伞",new Vector3(-1.4f,3,0),new Vector3(2.2f,.25f,2.2f),pink,.1f);a.Piece("饮料桌",new Vector3(1.4f,.5f,0),new Vector3(.8f,1,.8f),white);a.Piece("冰果汁",new Vector3(1.4f,1.17f,0),new Vector3(.17f,.3f,.17f),new Color(1,.55f,.12f),PrimitiveType.Cylinder);a.Piece("冰块",new Vector3(1.4f,1.36f,0),Vector3.one*.12f,new Color(.73f,.92f,1));
   var queen=RoyalArt.Girl(sunScene,false,true);queen.transform.localPosition=new Vector3(0,-.25f,-.2f);queen.transform.localRotation=Quaternion.Euler(0,180,0);foreach(Transform part in queen.transform)if(part.name=="鞋"||part.name=="小腿")part.localPosition+=new Vector3(0,.24f,.25f);queen.gameObject.AddComponent<CrownChallenge>().Initialize(Game);var cup=queen.Piece("公主手中冰果汁",new Vector3(.2f,1.16f,.2f),new Vector3(.14f,.24f,.14f),new Color(1,.64f,.14f),PrimitiveType.Cylinder);queen.gameObject.AddComponent<PrincessSip>().Initialize(Game,cup,queen.Arm);
   for(int i=0;i<2;i++){var server=RoyalArt.Girl(sunScene,false,false);server.gameObject.name="送饮料服务人员";server.transform.localPosition=new Vector3(i==0?-3:3,0,-1.5f);server.Piece("托盘",new Vector3(0,.9f,.45f),new Vector3(.6f,.04f,.35f),white);server.Piece(i==0?"冰奶昔":"果汁",new Vector3(0,1.05f,.45f),new Vector3(.16f,.28f,.16f),i==0?pink:new Color(1,.65f,.2f),PrimitiveType.Cylinder);server.gameObject.AddComponent<DrinkService>().Initialize(Game,server.transform.localPosition,new Vector3(i==0?-1:1,0,-.5f),i*3);}
   if(palacePrincess!=null)palacePrincess.gameObject.SetActive(false);sunEnd=Time.time+26;return true;
  }
 }
 public class DrinkService:MonoBehaviour {Sandbox game;Vector3 from,to;float offset;public void Initialize(Sandbox g,Vector3 a,Vector3 b,float delay){game=g;from=a;to=b;offset=Time.time+delay;}void Update(){if(game.Paused)return;float t=Mathf.PingPong(Mathf.Max(0,Time.time-offset)*.16f,1);transform.localPosition=Vector3.Lerp(from,to,t);}}
 public class PrincessSip:MonoBehaviour {Sandbox game;Transform cup,arm;public void Initialize(Sandbox g,Transform c,Transform a){game=g;cup=c;arm=a;}void Update(){if(game.Paused)return;bool fighting=GetComponent<CrownChallenge>().Active;cup.gameObject.SetActive(!fighting);if(fighting)return;float t=Mathf.SmoothStep(0,1,Mathf.Clamp01(Mathf.Sin(Time.time*1.2f)));cup.localPosition=Vector3.Lerp(new Vector3(.23f,1.1f,.2f),new Vector3(0,1.42f,.28f),t);cup.localRotation=Quaternion.Euler(t*30,0,0);arm.localRotation=Quaternion.Euler(-t*65,0,-t*25);}}
}
